package com.edgeos.launcher; import android.app.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class LockScreenActivity extends Activity{TextView clock;public void onCreate(Bundle b){super.onCreate(b);getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setGravity(Gravity.CENTER);r.setPadding(20,50,20,40);r.setBackground(new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TL_BR,new int[]{0xFF0B1020,0xFF3A4664}));TextView d=Ui.text(this,new SimpleDateFormat("EEEE, d MMMM",Locale.getDefault()).format(new Date()),18,Color.WHITE);r.addView(d,new LinearLayout.LayoutParams(-1,45));clock=Ui.text(this,new SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()),76,Color.WHITE);clock.setTypeface(null,android.graphics.Typeface.BOLD);r.addView(clock,new LinearLayout.LayoutParams(-1,100));TextView hint=Ui.text(this,"Swipe up to unlock",14,0xFFDDDDDD);r.addView(hint,new LinearLayout.LayoutParams(-1,0,1));r.setOnClickListener(v->finish());setContentView(r);}}
